#![cfg(feature="player")]
use fvid::audio::{AudioStream,AudioDecode};
use std::{io::Cursor,path::Path,time::Duration};
#[path="support/audio_capture.rs"] mod capture;
fn open(bytes:Vec<u8>)->fvid::playback_flac::FlacAudioReader{fvid::playback_flac::FlacAudioReader::open(Cursor::new(bytes),Default::default()).unwrap()}
#[test]
fn flac_multi_byte_coded_numbers_reach_index_and_actual_playback(){
 let base=Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/playback-errors/flac-coded-numbers");let manifest:serde_json::Value=serde_json::from_slice(&std::fs::read(base.join("manifest.json")).unwrap()).unwrap();let mut failures=Vec::new();let mut video=fvid::playback_native::NativeReader::software(Cursor::new(std::fs::read(base.join("video.mkv")).unwrap()),32<<20).unwrap();assert!(video.read_frame_raw().unwrap().is_some());assert!(video.read_frame_raw().unwrap().is_none());let info=std::fs::read(base.join("fixed-3.flac")).unwrap()[8..42].to_vec();
 for case in manifest["cases"].as_array().unwrap(){let name=case["file"].as_str().unwrap();let bytes=std::fs::read(base.join(name)).unwrap();let mut decoder=fvid::codec::flac_decoder::FlacDecoder::new(&bytes[8..42],44100,1).unwrap();let mut expected=Vec::new();let mut samples=0u64;for packet in case["packets"].as_array().unwrap(){let encoded=std::fs::read(base.join(packet["file"].as_str().unwrap())).unwrap();let count=packet["samples"].as_u64().unwrap();let level=packet["level"].as_i64().unwrap();let wanted=(0..count).flat_map(|_|((level as f32)/32768.0).to_le_bytes()).collect::<Vec<_>>();let frame=decoder.decode_packet(&encoded,samples as i64,count).unwrap().unwrap();assert_eq!(frame.packet.data,wanted,"{name}: independent nativepacketdecode");let pts=Duration::from_nanos((u128::from(samples)*1_000_000_000/44100)as u64);assert_eq!(frame.packet.presentation_time(),pts);expected.push((pts,wanted));samples+=count;}
 let source=match fvid::playback_flac::FlacAudioReader::open(Cursor::new(bytes.clone()),Default::default()){Ok(s)=>s,Err(e)=>{failures.push(format!("{name}: validstreamindexrefused{e}"));continue;}};assert_eq!(source.flac().frames.len(),expected.len(),"{name}: packetconservation");let end=Duration::from_nanos((u128::from(samples)*1_000_000_000/44100)as u64);for target in [expected[expected.len()/2].0,end]{capture::worker_check_with_seek(Box::new(open(bytes.clone())),&expected,Some(target));}
 }
 for name in manifest["headers"].as_array().unwrap(){let name=name.as_str().unwrap();let encoded=std::fs::read(base.join(name)).unwrap();let mut decoder=fvid::codec::flac_decoder::FlacDecoder::new(&info,44100,1).unwrap();assert!(decoder.decode_packet(&encoded,0,64).unwrap().is_some(),"{name}: canonicalnumbernativecodec");if fvid_media::owned_flac::frame_header(&encoded).is_none(){failures.push(format!("{name}: canonicalwidecodedheaderrefused"));}}
 for name in manifest["invalid"].as_array().unwrap(){let name=name.as_str().unwrap();let encoded=std::fs::read(base.join(name)).unwrap();assert!(fvid_media::owned_flac::frame_header(&encoded).is_none(),"{name}: invalidcodednumberheaderadmitted");let mut decoder=fvid::codec::flac_decoder::FlacDecoder::new(&info,44100,1).unwrap();assert!(decoder.decode_packet(&encoded,0,64).is_err(),"{name}: invalidcodednumbercodecaccepted");}
 assert!(failures.is_empty(),"{}",failures.join("; "));
}
